=pod

=head2 Service Client: Google::Spanner::Executor::V1::CloudExecutor::SpannerExecutorProxyClient

Client stub representing the remote C<SpannerExecutorProxy> gRPC service. Delegates call dispatching to L<Google::gRPC::Client>.

=head3 target

The endpoint target address. Defaults to C<spanner.googleapis.com:443>.

=head3 credentials

The authentication credentials provider. Defaults to application default credentials via L<Google::Auth>.

=cut

use Moo;
use Google::Auth;
use Google::gRPC::Client;

has credentials => ( is => 'ro', default => sub { Google::Auth->default() } );
has target      => ( is => 'ro', default => 'spanner.googleapis.com:443' );

has _grpc_client => (
    is => 'ro',
    lazy => 1,
    builder => sub {
        my $self = shift;
        return Google::gRPC::Client->new(
            target     => $self->target,
            auth_token => $self->credentials->get_token(),
        );
    }
);

sub execute_action_async {
    my ($self, $args) = @_;
    my $req = ref($args) eq 'HASH'
        ? Google::Spanner::Executor::V1::CloudExecutor::SpannerAsyncActionRequest->new($args)
        : $args;
    return $self->_grpc_client->call({
        service        => 'google.spanner.executor.v1.SpannerExecutorProxy',
        method         => 'ExecuteActionAsync',
        request        => $req,
        response_class => 'Google::Spanner::Executor::V1::CloudExecutor::SpannerAsyncActionResponse',
    });
}

1;

