=head2 Google::Spanner::Executor::V1::CloudExecutor::Concurrency

Concurrency for read-only transactions.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->staleness_seconds() >> / C<< $msg->staleness_seconds($value) >>

Type: C<Double>

Indicates a read at a consistent timestamp that is specified relative to
now. That is, if the caller has specified an exact staleness of s
seconds, we will read at now - s.

=item * C<< $msg->min_read_timestamp_micros() >> / C<< $msg->min_read_timestamp_micros($value) >>

Type: C<Int64>

Indicates a boundedly stale read that reads at a timestamp >= T.

=item * C<< $msg->max_staleness_seconds() >> / C<< $msg->max_staleness_seconds($value) >>

Type: C<Double>

Indicates a boundedly stale read that is at most N seconds stale.

=item * C<< $msg->exact_timestamp_micros() >> / C<< $msg->exact_timestamp_micros($value) >>

Type: C<Int64>

Indicates a read at a consistent timestamp.

=item * C<< $msg->strong() >> / C<< $msg->strong($value) >>

Type: C<Bool>

Indicates a strong read, must only be set to true, or unset.

=item * C<< $msg->batch() >> / C<< $msg->batch($value) >>

Type: C<Bool>

Indicates a batch read, must only be set to true, or unset.

=item * C<< $msg->snapshot_epoch_read() >> / C<< $msg->snapshot_epoch_read($value) >>

Type: C<Bool>

True if exact_timestamp_micros is set, and the chosen timestamp is that of
a snapshot epoch.

=item * C<< $msg->snapshot_epoch_root_table() >> / C<< $msg->snapshot_epoch_root_table($value) >>

Type: C<String>

If set, this is a snapshot epoch read constrained to read only the
specified log scope root table, and its children. Will not be set for full
database epochs.

=item * C<< $msg->batch_read_timestamp_micros() >> / C<< $msg->batch_read_timestamp_micros($value) >>

Type: C<Int64>

Set only when batch is true.

=back

