=head2 Google::Spanner::Executor::V1::CloudExecutor::ChangeStreamRecord

Raw ChangeStream records.
Encodes one of: DataChangeRecord, HeartbeatRecord, ChildPartitionsRecord
returned from the ChangeStream API.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->data_change() >> / C<< $msg->data_change($value) >>

Type: C<Message> (L<Google::Spanner::Executor::V1::CloudExecutor::DataChangeRecord>)

Data change record.

=item * C<< $msg->child_partition() >> / C<< $msg->child_partition($value) >>

Type: C<Message> (L<Google::Spanner::Executor::V1::CloudExecutor::ChildPartitionsRecord>)

Child partitions record.

=item * C<< $msg->heartbeat() >> / C<< $msg->heartbeat($value) >>

Type: C<Message> (L<Google::Spanner::Executor::V1::CloudExecutor::HeartbeatRecord>)

Heartbeat record.

=back

=head2 Google::Spanner::Executor::V1::CloudExecutor::DataChangeRecord

ChangeStream data change record.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->commit_time() >> / C<< $msg->commit_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The timestamp in which the change was committed.

=item * C<< $msg->record_sequence() >> / C<< $msg->record_sequence($value) >>

Type: C<String>

The sequence number for the record within the transaction.

=item * C<< $msg->transaction_id() >> / C<< $msg->transaction_id($value) >>

Type: C<String>

A globally unique string that represents the transaction in which the
change was committed.

=item * C<< $msg->is_last_record() >> / C<< $msg->is_last_record($value) >>

Type: C<Bool>

Indicates whether this is the last record for a transaction in the current
partition.

=item * C<< $msg->table() >> / C<< $msg->table($value) >>

Type: C<String>

Name of the table affected by the change.

=item * C<< $msg->column_types() >> / C<< $msg->column_types($value) >>

Type: C<Message> (L<Google::Spanner::Executor::V1::CloudExecutor::DataChangeRecord::ColumnType>)

Column types defined in the schema.

=item * C<< $msg->mods() >> / C<< $msg->mods($value) >>

Type: C<Message> (L<Google::Spanner::Executor::V1::CloudExecutor::DataChangeRecord::Mod>)

Changes made in the transaction.

=item * C<< $msg->mod_type() >> / C<< $msg->mod_type($value) >>

Type: C<String>

Describes the type of change. One of INSERT, UPDATE or DELETE.

=item * C<< $msg->value_capture_type() >> / C<< $msg->value_capture_type($value) >>

Type: C<String>

One of value capture type: NEW_VALUES, OLD_VALUES, OLD_AND_NEW_VALUES.

=item * C<< $msg->record_count() >> / C<< $msg->record_count($value) >>

Type: C<Int64>

Number of records in transactions.

=item * C<< $msg->partition_count() >> / C<< $msg->partition_count($value) >>

Type: C<Int64>

Number of partitions in transactions.

=item * C<< $msg->transaction_tag() >> / C<< $msg->transaction_tag($value) >>

Type: C<String>

Transaction tag info.

=item * C<< $msg->is_system_transaction() >> / C<< $msg->is_system_transaction($value) >>

Type: C<Bool>

Whether the transaction is a system transactionn.

=back

=head2 Google::Spanner::Executor::V1::CloudExecutor::ChildPartitionsRecord

ChangeStream child partition record.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->start_time() >> / C<< $msg->start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Data change records returned from child partitions in this child partitions
record will have a commit timestamp greater than or equal to start_time.

=item * C<< $msg->record_sequence() >> / C<< $msg->record_sequence($value) >>

Type: C<String>

A monotonically increasing sequence number that can be used to define the
ordering of the child partitions record when there are multiple child
partitions records returned with the same start_time in a particular
partition.

=item * C<< $msg->child_partitions() >> / C<< $msg->child_partitions($value) >>

Type: C<Message> (L<Google::Spanner::Executor::V1::CloudExecutor::ChildPartitionsRecord::ChildPartition>)

A set of child partitions and their associated information.

=back

